-- Ten read-only daily workflows. Runtime tool permissions remain code allowlisted.
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, category=EXCLUDED.category, sort_order=EXCLUDED.sort_order, selectable=TRUE, enabled=TRUE, updated_at=NOW();
UPDATE cadu_chat_plugin_versions SET is_current=FALSE WHERE plugin_id IN ('market-radar', 'audience-map', 'investment-simulator', 'media-plan-audit', 'campaign-tracker', 'creative-concept', 'channel-copy', 'page-review', 'meeting-copilot', 'client-delivery') AND version <> '1.0.0' AND is_current;
ON CONFLICT (plugin_id, version) DO UPDATE SET maturity=EXCLUDED.maturity, description=EXCLUDED.description, manifest=EXCLUDED.manifest, is_current=TRUE;
